package io.github.origincts;

import de.robv.android.xposed.XC_MethodHook;
import de.robv.android.xposed.XposedHelpers;

/**
 * Grants unprivileged Google App the capability to initialize Android's native Hotword Detection
 * Service and enroll keyphrases without needing to be an actual /product/priv-app system app.
 */
final class NativeVoiceHook {
    static void install(ClassLoader loader) {
        try {
            // 1. Hook Stub enforcePermission helpers generated by AIDL
            try {
                Class<?> stub = XposedHelpers.findClass(
                        "com.android.internal.app.IVoiceInteractionManagerService$Stub", loader);
                XposedHelpers.findAndHookMethod(stub, "initAndVerifyDetector_enforcePermission",
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (HookSettings.enabled(FeatureState.VOICE)) {
                                    param.setResult(null);
                                }
                            }
                        });
                XposedHelpers.findAndHookMethod(stub, "updateState_enforcePermission",
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (HookSettings.enabled(FeatureState.VOICE)) {
                                    param.setResult(null);
                                }
                            }
                        });
            } catch (Throwable t) {
                HookEntry.log("Stub enforcePermission hooks warning: " + t);
            }

            // 2. Hook VoiceInteractionManagerService$VoiceInteractionManagerServiceStub
            Class<?> serviceStub = XposedHelpers.findClass(
                    "com.android.server.voiceinteraction.VoiceInteractionManagerService$VoiceInteractionManagerServiceStub",
                    loader);

            try {
                XposedHelpers.findAndHookMethod(serviceStub, "enforceCallerAllowedToEnrollVoiceModel",
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (HookSettings.enabled(FeatureState.VOICE)) {
                                    param.setResult(null);
                                }
                            }
                        });
            } catch (Throwable t) {
                HookEntry.log("enforceCallerAllowedToEnrollVoiceModel hook warning: " + t);
            }

            try {
                XposedHelpers.findAndHookMethod(serviceStub, "isCallerPreinstalledAssistant",
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (HookSettings.enabled(FeatureState.VOICE)) {
                                    param.setResult(true);
                                }
                            }
                        });
            } catch (Throwable t) {
                HookEntry.log("isCallerPreinstalledAssistant hook warning: " + t);
            }

            try {
                XposedHelpers.findAndHookMethod(serviceStub, "enforceCallingPermission", String.class,
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (!HookSettings.enabled(FeatureState.VOICE)) return;
                                String perm = (String) param.args[0];
                                if (isVoicePermission(perm)) {
                                    param.setResult(null);
                                }
                            }
                        });
            } catch (Throwable t) {
                HookEntry.log("enforceCallingPermission hook warning: " + t);
            }

            try {
                XposedHelpers.findAndHookMethod(serviceStub, "isCallerHoldingPermission", String.class,
                        new XC_MethodHook() {
                            @Override
                            protected void beforeHookedMethod(MethodHookParam param) {
                                if (!HookSettings.enabled(FeatureState.VOICE)) return;
                                String perm = (String) param.args[0];
                                if (isVoicePermission(perm)) {
                                    param.setResult(true);
                                }
                            }
                        });
            } catch (Throwable t) {
                HookEntry.log("isCallerHoldingPermission hook warning: " + t);
            }

            HookEntry.log("NativeVoiceHook installed in VoiceInteractionManagerService");
        } catch (Throwable failure) {
            HookEntry.log("NativeVoiceHook unavailable: " + failure);
        }
    }

    private static boolean isVoicePermission(String perm) {
        return "android.permission.MANAGE_HOTWORD_DETECTION".equals(perm)
                || "android.permission.CAPTURE_AUDIO_HOTWORD".equals(perm)
                || "android.permission.MANAGE_VOICE_KEYPHRASES".equals(perm)
                || "android.permission.MANAGE_SOUND_TRIGGER".equals(perm)
                || "android.permission.SOUND_TRIGGER_RUN_IN_BATTERY_SAVER".equals(perm)
                || "android.permission.KEYPHRASE_ENROLLMENT_APPLICATION".equals(perm)
                || "android.permission.RECORD_AUDIO".equals(perm);
    }
}
